contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        require(x <= c.balanceOf(address(this)));

        uint256 beforeOwner = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterOwner = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || afterOwner == beforeOwner - x);
    }

    receive() external payable {}
}

