import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 x) internal {
        vm.assume(x <= c.balanceOf(address(this)));
        uint256 beforeOwner;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeOwner = __r; } catch { return; }
        bool reverted;
        try c.burn(x) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterOwner;
        try c.balanceOf(address(this)) returns (uint256 __r) { afterOwner = __r; } catch { return; }
        assertTrue(reverted || afterOwner == beforeOwner - x);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

